 static int checks; static void Check(bool x,string m){checks++;if(!x)throw new Exception(m);}
 static Qualification.Request Request(string root,int limit){string saved=Path.Combine(root,"saved.sldprt");if(!File.Exists(saved))File.WriteAllText(saved,"native-qualification-offline-fixture");string target=Path.Combine(root,"case-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(target);string copy=Path.Combine(target,"copy.sldprt");File.Copy(saved,copy);var d=new Dictionary<string,object>{{"schema_version",1},{"expected_process_id",25064},{"expected_process_creation_time",1794340655.896},{"expected_document_path",copy},{"expected_source_sha256",Qualification.Hash(copy)},{"protected_document_path",saved},{"protected_source_sha256",Qualification.Hash(saved)},{"qualification_root",target},{"expected_sw_configuration","test"},{"expected_cam_configuration","test"},{"expected_host_module_version_id",typeof(IslandAddin).Module.ModuleVersionId.ToString()},{"native_receipt_path",Path.Combine(target,"result.json")},{"expected_cad_fingerprint",Qualification.Json().DeserializeObject(File.ReadAllText(Path.Combine(root,"CAD_BASELINE.json")))},{"owner_setup_native_id",64},{"operation_setup_native_id",65},{"axis_native",new[]{0.0,0.0,-1.0}},{"origin_native",new[]{0.0,0.0,0.0}},{"outer_sketch_name","CAM_UPPER_PROFILE_R25"},{"island_sketch_names",new[]{"CAM_GUIDE_FULL_25","CAM_GUIDE_FULL_155","CAM_GUIDE_FULL_205","CAM_GUIDE_FULL_335"}},{"depth_native",13.2},{"expected_shape",2},{"island_count_limit",limit}};return Qualification.Parse(Qualification.Json().Serialize(d));}
 class Fake:Qualification.IBackend {
