  public void Prepare(){if(Fail=="prepare")throw new Exception("prepare");}public void Boundary(bool clean){if(Fail=="boundary")throw new Exception("boundary");}
  public Dictionary<string,object> Capture(){return new Dictionary<string,object>{{"cad_fingerprint",Q.Cad},{"feature_count",CreateCalls},{"operation_count",0}};}
  public object Create(){CreateCalls++;if(Fail=="create")throw new Exception("create");local=new object();return local;}
  public int Identify(object x){SameObject&=Object.ReferenceEquals(x,local);return 111;}
  public bool Add(object x,int index){SameObject&=Object.ReferenceEquals(x,local);AddCalls++;if(Fail=="add"||Fail=="add2"&&AddCalls==2)throw new System.Runtime.InteropServices.COMException("native fault",unchecked((int)0x80010105));if(Fail=="false")return false;Count++;return true;}
  public Dictionary<string,object> Header(int id){HeaderCalls++;return new Dictionary<string,object>{{"native_id",id},{"owner_setup_native_id",64},{"shape",2},{"volume_type",2},{"suppressed",false},{"axis_native",new[]{0.0,0.0,-1.0}},{"depth_native",13.2},{"taper_angle_native",0.0},{"island_count",Fail=="header"?7:Count},{"sketch_count",Count+1},{"sketch_names",new[]{Q.Outer}.Concat(Q.Islands.Take(Count)).ToArray()}};}
  public object Chains(int id,int count){if(Fail=="chains")throw new Exception("chains");return new Dictionary<string,object>{{"read_complete",true}};}
  public void Quiet(){}public void Dispose(){Disposed++;if(Fail=="cleanup")throw new Exception("cleanup");}
  public object Messages{get{return new Dictionary<string,object>{{"subscribed",true},{"disconnected",Disposed==1},{"active",false},{"event_count",Fail=="lateevent"?1:0},{"overflow",0},{"callback_error_count",0},{"cleanup_error",null}};}}
 }
 static void RunCase(string root,string fail,int limit,int creates,int adds,string status){var q=Request(root,limit);var f=new Fake{Q=q,Fail=fail};var r=Qualification.Run(q,f,Qualification.Initial());Check(f.CreateCalls==creates,"create bound "+fail);Check(f.AddCalls==adds,"add bound "+fail);Check(f.SameObject,"retained object "+fail);Check((string)r["status"]==status,"status "+fail);Check(f.Disposed==1,"cleanup once "+fail);Check(Qualification.Same(Qualification.Json().DeserializeObject(Qualification.Json().Serialize(r)),Qualification.Json().DeserializeObject(File.ReadAllText(q.Receipt))),"durable receipt equality "+fail);if(creates>0){Check(File.Exists(q.Marker),"marker persists "+fail);var rejected=new Fake{Q=q};var r2=Qualification.Run(q,rejected,Qualification.Initial());Check(rejected.CreateCalls==0&&rejected.AddCalls==0&&(string)r2["status"]=="error","no replay "+fail);Check(!((bool)r["Save_attempted"])&&!((bool)r["GOP_attempted"])&&!((bool)r["GTP_attempted"]),"forbidden flags "+fail);}if(fail=="add"||fail=="add2"){var actions=(List<Dictionary<string,object>>)r["actions"];var last=actions.Last();Check((bool)last["pending"]&&!(bool)last["returned"]&&last.ContainsKey("exception"),"pending exception retained");Check(!(bool)r["readback_verified"],"failed mutation not upgraded");}}
 static Dictionary<string,object> SwObservation(Qualification.Request q){return new Dictionary<string,object>{{"process_id",q.Pid},{"application_process_id",q.Pid},{"process_creation_time",q.Created},{"active_present",true},{"document_type",1},{"path",q.Copy},{"sw_configuration",q.SwConfig},{"needs_save",false},{"loaded_collection_valid",true},{"loaded_count",1},{"loaded_document_typed",true},{"loaded_paths",new[]{q.Copy}}};}
 static Dictionary<string,object> CamObservation(Qualification.Request q,uint feature){return new Dictionary<string,object>{{"present",true},{"document_type",1},{"configuration_present",true},{"active_configuration",q.CamConfig},{"cam_configuration",q.CamConfig},{"sw_configuration",q.SwConfig},{"machine_present",true},{"machine_type",1},{"setup_collection_present",true},{"setup_count",1},{"setup_present",true},{"setup_id_returned",true},{"setup_id",q.SetupId},{"axis_native",q.Axis},{"origin_native",q.Origin},{"feature_collection_present",true},{"feature_count",feature==0?0:1},{"feature_count_after",feature==0?0:1},{"feature_ids",feature==0?new uint[0]:new[]{feature}},{"feature_present",true},{"feature_id_returned",true},{"operation_setup_collection_present",true},{"operation_setup_count",1},{"operation_setup_present",true},{"operation_setup_id_returned",true},{"operation_setup_id",q.OpSetupId},{"operation_collection_present",true},{"operation_count",0},{"setup_count_after",1},{"operation_setup_count_after",1},{"reference_equals_retained_telemetry",false}};}
 static void RejectedObservation(Dictionary<string,object> row,string code,Action<Action> validate){int records=0;string observed=null,error=null;try{validate(()=>{records++;observed=Qualification.Json().Serialize(row);});}catch(InvalidOperationException e){error=e.Message;}Check(error==code,"specific boundary error "+code);Check(records==1,"observation precedes rejection "+code);Check(observed==Qualification.Json().Serialize(row),"full rejected scalar observation "+code);}
 static void BoundaryValidationCases(string root){
  var q=Request(root,1);int recorded=0;Qualification.ValidateSwBoundary(q,SwObservation(q),true,()=>recorded++);Check(recorded==1,"single active target accepted and recorded");
  foreach(uint feature in new uint[]{0,111}){recorded=0;Qualification.ValidateCamContext(q,CamObservation(q,feature),feature,()=>recorded++);Check(recorded==1,"logical CAM context accepted despite false wrapper telemetry "+feature);}
  var sw=SwObservation(q);sw["loaded_count"]=2;sw["loaded_paths"]=new[]{q.Copy,q.Protected};RejectedObservation(sw,"SOLE_QUALIFICATION_DOCUMENT_REQUIRED",r=>Qualification.ValidateSwBoundary(q,sw,true,r));
  sw=SwObservation(q);sw["loaded_paths"]=new[]{q.Protected};RejectedObservation(sw,"SOLE_QUALIFICATION_DOCUMENT_PATH_CHANGED",r=>Qualification.ValidateSwBoundary(q,sw,true,r));
  sw=SwObservation(q);sw["path"]=q.Protected;RejectedObservation(sw,"ACTIVE_COPY_PATH_CHANGED",r=>Qualification.ValidateSwBoundary(q,sw,true,r));
  sw=SwObservation(q);sw["sw_configuration"]="other";RejectedObservation(sw,"ACTIVE_COPY_CONFIGURATION_CHANGED",r=>Qualification.ValidateSwBoundary(q,sw,true,r));
  sw=SwObservation(q);sw["process_creation_time"]=q.Created+2;RejectedObservation(sw,"PROCESS_ID_LIFETIME_CHANGED",r=>Qualification.ValidateSwBoundary(q,sw,true,r));
  sw=SwObservation(q);sw["needs_save"]=true;RejectedObservation(sw,"CLEAN_SAVED_COPY_REQUIRED",r=>Qualification.ValidateSwBoundary(q,sw,true,r));
  // Same setup IDs must never make a wrong document/configuration or changed inventory acceptable.
  foreach(string key in new[]{"active_configuration","cam_configuration","sw_configuration"}){var c=CamObservation(q,0);c[key]="other";RejectedObservation(c,"CAM_CONFIGURATION_CHANGED",r=>Qualification.ValidateCamContext(q,c,0,r));}
  foreach(string key in new[]{"present","configuration_present","machine_present"}){var c=CamObservation(q,0);c[key]=false;string error=key=="present"?"CAM_ACTIVE_DOCUMENT_ABSENT":key=="configuration_present"?"CAM_CONFIGURATION_ABSENT":"CAM_MILL_MACHINE_CHANGED";RejectedObservation(c,error,r=>Qualification.ValidateCamContext(q,c,0,r));}
  var cam=CamObservation(q,0);cam["document_type"]=2;RejectedObservation(cam,"CAM_DOCUMENT_TYPE_CHANGED",r=>Qualification.ValidateCamContext(q,cam,0,r));
  cam=CamObservation(q,0);cam["setup_id"]=64;cam["operation_setup_id"]=65;cam["axis_native"]=new[]{0.0,0.0,1.0};RejectedObservation(cam,"CAM_SETUP_AXIS_CHANGED",r=>Qualification.ValidateCamContext(q,cam,0,r));
  cam=CamObservation(q,0);cam["origin_native"]=new[]{1.0,0.0,0.0};RejectedObservation(cam,"CAM_SETUP_ORIGIN_CHANGED",r=>Qualification.ValidateCamContext(q,cam,0,r));
  cam=CamObservation(q,111);cam["feature_ids"]=new uint[]{112};RejectedObservation(cam,"CAM_FEATURE_MEMBERSHIP_CHANGED",r=>Qualification.ValidateCamContext(q,cam,111,r));
  cam=CamObservation(q,111);RejectedObservation(cam,"CAM_FEATURE_MEMBERSHIP_CHANGED",r=>Qualification.ValidateCamContext(q,cam,0,r));
  cam=CamObservation(q,0);RejectedObservation(cam,"CAM_FEATURE_MEMBERSHIP_CHANGED",r=>Qualification.ValidateCamContext(q,cam,111,r));
  cam=CamObservation(q,111);cam["feature_count_after"]=0;RejectedObservation(cam,"CAM_FEATURE_MEMBERSHIP_CHANGED",r=>Qualification.ValidateCamContext(q,cam,111,r));
  cam=CamObservation(q,0);cam["operation_count"]=1;RejectedObservation(cam,"CAM_EMPTY_OPERATIONS_REQUIRED",r=>Qualification.ValidateCamContext(q,cam,0,r));
  cam=CamObservation(q,0);cam["setup_count"]=2;RejectedObservation(cam,"CAM_EXACT_SETUP_REQUIRED",r=>Qualification.ValidateCamContext(q,cam,0,r));
  cam=CamObservation(q,0);cam["setup_id"]=66;RejectedObservation(cam,"CAM_SETUP_NATIVE_ID_CHANGED",r=>Qualification.ValidateCamContext(q,cam,0,r));
  cam=CamObservation(q,0);cam["operation_setup_id"]=67;RejectedObservation(cam,"CAM_OPERATION_SETUP_NATIVE_ID_CHANGED",r=>Qualification.ValidateCamContext(q,cam,0,r));
  cam=CamObservation(q,0);cam["setup_count_after"]=0;RejectedObservation(cam,"CAM_SETUP_COLLECTION_DRIFT",r=>Qualification.ValidateCamContext(q,cam,0,r));
 }
