 static void RejectCoordinates(Func<double[]> call,string error){string actual=null;try{call();}catch(InvalidOperationException e){actual=e.Message;}Check(actual!=null&&actual.StartsWith(error,StringComparison.Ordinal),"coordinate rejection "+error);}
 static void CoordinateDecoderCases(string root){
  Check(Qualification.Same(Qualification.NativeBackend.Vec(new[]{0.0,0.0,-1.0}),new[]{0.0,0.0,-1.0}),"observed Axis Double[] representation");
  Check(Qualification.Same(Qualification.NativeBackend.Pos(new object[]{0,1.5,-2m}),new[]{0.0,1.5,-2.0}),"VARIANT numeric coordinate array retains order/units");
  var nonzero=Array.CreateInstance(typeof(double),new[]{3},new[]{1});nonzero.SetValue(4.0,1);nonzero.SetValue(5.0,2);nonzero.SetValue(6.0,3);Check(Qualification.Same(Qualification.NativeBackend.Pos(nonzero),new[]{4.0,5.0,6.0}),"rank-one SAFEARRAY lower bound respected");
  foreach(object raw in new object[]{new double[0],new double[2],new double[4],new double[1,3]}){RejectCoordinates(()=>Qualification.NativeBackend.Vec(raw),"COORDINATE_ARRAY_SHAPE");RejectCoordinates(()=>Qualification.NativeBackend.Pos(raw),"COORDINATE_ARRAY_SHAPE");}
  foreach(object scalar in new object[]{null,true,"0",new object(),DateTime.UtcNow}){var raw=new object[]{0.0,0.0,scalar};RejectCoordinates(()=>Qualification.NativeBackend.Vec(raw),"COORDINATE_SCALAR_TYPE");RejectCoordinates(()=>Qualification.NativeBackend.Pos(raw),"COORDINATE_SCALAR_TYPE");}
  foreach(double scalar in new[]{Double.NaN,Double.PositiveInfinity,Double.NegativeInfinity}){var raw=new[]{0.0,0.0,scalar};RejectCoordinates(()=>Qualification.NativeBackend.Vec(raw),"COORDINATE_NONFINITE");RejectCoordinates(()=>Qualification.NativeBackend.Pos(raw),"COORDINATE_NONFINITE");}
  var vector=new FakeVector();Check(Qualification.Same(Qualification.NativeBackend.Vec(vector),vector.Values)&&vector.Reads==1,"typed unit-vector getter exactly once");
  var position=new FakePosition();Check(Qualification.Same(Qualification.NativeBackend.Pos(position),position.Values)&&position.Reads==1,"typed position getter exactly once");
  RejectCoordinates(()=>Qualification.NativeBackend.Vec(position),"NATIVE_VECTOR_REPRESENTATION:");Check(position.Reads==1,"wrong interface does not invoke position getter");
  RejectCoordinates(()=>Qualification.NativeBackend.Pos(vector),"NATIVE_POSITION_REPRESENTATION:");Check(vector.Reads==1,"wrong interface does not invoke vector getter");
  RejectCoordinates(()=>Qualification.NativeBackend.Vec(null),"NATIVE_VECTOR_REPRESENTATION:null");RejectCoordinates(()=>Qualification.NativeBackend.Pos(new object()),"NATIVE_POSITION_REPRESENTATION:System.Object");
  vector.Values=new[]{0.0,0.0,Double.NaN};RejectCoordinates(()=>Qualification.NativeBackend.Vec(vector),"COORDINATE_NONFINITE");Check(vector.Reads==2,"invalid typed coordinate is not retried");
  vector.Throw=true;bool threw=false;try{Qualification.NativeBackend.Vec(vector);}catch(System.Runtime.InteropServices.COMException e){threw=e.ErrorCode==unchecked((int)0x80010105);}Check(threw&&vector.Reads==3,"native coordinate exception propagates without retry");
  var q=Request(root,1);var context=CamObservation(q,0);context["axis_native"]=Qualification.NativeBackend.Vec(new[]{0.0,0.0,-2.0});RejectedObservation(context,"CAM_SETUP_AXIS_CHANGED",r=>Qualification.ValidateCamContext(q,context,0,r));
  context=CamObservation(q,0);context["origin_native"]=Qualification.NativeBackend.Pos(new[]{0.0,0.0,1.0});RejectedObservation(context,"CAM_SETUP_ORIGIN_CHANGED",r=>Qualification.ValidateCamContext(q,context,0,r));
 }
