 static void SetupOriginCases(string root){
  var setup=new FakeSetup();var observed=Qualification.NativeBackend.SetupOrigin(setup);Check(Qualification.Same(observed,new[]{0.0,0.0,0.0})&&setup.OriginReads==1&&setup.ReferencePointReads==0,"setup origin uses documented getter once and never reference point");
  var point=Qualification.NativeBackend.Pos(setup.IGetRefPoint());Check(Qualification.Same(point,new[]{0.0,0.0,26.0})&&!Qualification.Same(point,observed),"reference point26 and origin0 have distinct semantics");
  var q=Request(root,1);var context=CamObservation(q,0);context["origin_native"]=observed;int recorded=0;Qualification.ValidateCamContext(q,context,0,()=>recorded++);Check(recorded==1,"zero setup offsets accepted without adopting reference point26");
  setup.OriginValues=new[]{0.0,0.0,26.0};context=CamObservation(q,0);context["origin_native"]=Qualification.NativeBackend.SetupOrigin(setup);RejectedObservation(context,"CAM_SETUP_ORIGIN_CHANGED",r=>Qualification.ValidateCamContext(q,context,0,r));
  setup.OriginValues=new[]{0.0,Double.NaN,0.0};RejectCoordinates(()=>Qualification.NativeBackend.SetupOrigin(setup),"COORDINATE_NONFINITE");Check(setup.OriginReads==3,"nonfinite origin is not retried");
  setup.Throw=true;bool threw=false;try{Qualification.NativeBackend.SetupOrigin(setup);}catch(System.Runtime.InteropServices.COMException e){threw=e.ErrorCode==unchecked((int)0x80010105);}Check(threw&&setup.OriginReads==4,"origin getter failure propagates without reference-point fallback");
  RejectCoordinates(()=>Qualification.NativeBackend.SetupOrigin(null),"MILL_SETUP_REQUIRED_FOR_ORIGIN");Check(setup.ReferencePointReads==1,"production origin path never invokes reference-point getter");
 }
 static void Main(string[] argv){string root=Path.GetFullPath(argv[0]);BoundaryValidationCases(root);CoordinateDecoderCases(root);SetupOriginCases(root);RunCase(root,"",1,1,1,"islands_observed_ram_only");RunCase(root,"",4,1,4,"islands_observed_ram_only");RunCase(root,"prepare",1,0,0,"error");RunCase(root,"boundary",1,0,0,"error");RunCase(root,"create",1,1,0,"uncertain");RunCase(root,"add",1,1,1,"uncertain");RunCase(root,"false",4,1,1,"uncertain");RunCase(root,"add2",4,1,2,"uncertain");RunCase(root,"header",4,1,0,"uncertain");RunCase(root,"chains",1,1,1,"uncertain");RunCase(root,"cleanup",1,1,1,"uncertain");RunCase(root,"lateevent",1,1,1,"uncertain");
  foreach(int n in new[]{0,2,3,5}){bool rejected=false;try{Request(root,n);}catch{rejected=true;}Check(rejected,"limit rejected "+n);}
  var nullResult=Qualification.Json().DeserializeObject(Qualification.Execute(null,0,"{}")) as Dictionary<string,object>;Check((string)nullResult["status"]=="error"&&!(bool)nullResult["mutation_attempted"],"invalid request no app");
  Console.WriteLine(Qualification.Json().Serialize(new Dictionary<string,object>{{"status","passed"},{"checks",checks},{"native_calls",0},{"COM_activation",false}}));
 }
